var hook = $('Ask Webhook').first().json;
var body = hook.body || hook;
var who = ($('Verify Staff').first().json || {}).body || {};
var message = String(body.message || '').trim();
var now = new Date();
return [{ json: {
  message: message,
  staff_email: who.email || 'unknown',
  today: now.toISOString().slice(0,10),
  now_iso: now.toISOString(),
  detected_language: String(body.detected_language || '').trim()
} }];

var histRaw = $('Load Recent History').first().json;
var histBody = (histRaw && histRaw.body !== undefined) ? histRaw.body : histRaw;
var rows = Array.isArray(histBody) ? histBody : [];
rows = rows.slice().reverse();
var lines = [];
for (var i = 0; i < rows.length; i++) {
  var r = rows[i];
  lines.push((r.role === 'user' ? 'Staff' : 'Assistant') + ': ' + String(r.content || '').slice(0, 300));
}
var historyText = lines.length ? lines.join('\n') : '(no earlier messages today)';
var current = $('Normalize Ask Input').first().json.message;
return [{ json: {
  prompt_text: 'RECENT CONVERSATION:\n' + historyText + '\n\nNEW MESSAGE FROM STAFF:\n' + current
} }];

var ctxRaw = $('Fetch Business Context').first().json;
var ctxRows = (ctxRaw && ctxRaw.body !== undefined) ? ctxRaw.body : ctxRaw;
ctxRows = Array.isArray(ctxRows) ? ctxRows : [];
var ctxLines = ctxRows.map(function(r){ return r.key + ': ' + r.value; });
var contextText = ctxLines.length ? ctxLines.join('\n') : '(context unavailable)';

var queryResult = $('Run Query').first().json;
var data = (queryResult && queryResult.body !== undefined) ? queryResult.body : queryResult;
var question = $('Normalize Ask Input').first().json.message;

var data2 = null;
try {
  var q2 = $('Classify & Extract').first().json.output.query_kind_2;
  if (q2) {
    var queryResult2 = $('Run Query 2').first().json;
    data2 = (queryResult2 && queryResult2.body !== undefined) ? queryResult2.body : queryResult2;
  }
} catch (e) { data2 = null; }

var prompt = 'RESTAURANT INFO (always true - use this for hours/address/policy questions):\n' + contextText +
  '\n\nSTAFF QUESTION:\n' + question + '\n\nREAL DATA FROM THE DATABASE (the only source for numbers like sales, stock, orders):\n' + JSON.stringify(data, null, 2);
if (data2) {
  prompt += '\n\nREAL DATA FOR THE SECOND PART OF THE QUESTION:\n' + JSON.stringify(data2, null, 2);
}
return [{ json: { answer_prompt: prompt } }];

function norm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function levenshtein(a, b) {
  var m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  var prev = [];
  for (var j = 0; j <= n; j++) prev.push(j);
  for (var i = 1; i <= m; i++) {
    var cur = [i];
    for (var j2 = 1; j2 <= n; j2++) {
      var cost = a[i-1] === b[j2-1] ? 0 : 1;
      cur.push(Math.min(prev[j2] + 1, cur[j2-1] + 1, prev[j2-1] + cost));
    }
    prev = cur;
  }
  return prev[n];
}
function candidateKeys(fullName) {
  var keys = [norm(fullName)];
  var slash = fullName.indexOf(' / ');
  if (slash > -1) keys.push(norm(fullName.slice(0, slash)));
  var noParen = fullName.replace(/\s*\([^)]*\)\s*$/, '').trim();
  if (noParen && noParen !== fullName) keys.push(norm(noParen));
  var dash = fullName.indexOf(' - ');
  if (dash > -1) keys.push(norm(fullName.slice(0, dash)));
  return keys;
}
function roundQty(n) { return Math.round((Number(n) || 0) * 100) / 100; }

var invRaw = $('Fetch Full Inventory').first().json;
var inv = (invRaw && invRaw.body !== undefined) ? invRaw.body : invRaw;
inv = (inv && inv[0]) ? inv[0] : inv;
var menuItems = (inv && inv.menu_items) || [];
var ingredients = (inv && inv.ingredients) || [];

var items = (($('Classify & Extract').first().json.output) || {}).restock_items || [];

function findMatch(rawName) {
  var key = norm(rawName);
  if (!key) return null;
  var i, k, keys;
  for (i = 0; i < menuItems.length; i++) {
    keys = candidateKeys(menuItems[i].item_name);
    for (k = 0; k < keys.length; k++) { if (keys[k] === key) return { entity_type: 'menu_item', row: menuItems[i] }; }
  }
  for (i = 0; i < ingredients.length; i++) {
    keys = candidateKeys(ingredients[i].name);
    for (k = 0; k < keys.length; k++) { if (keys[k] === key) return { entity_type: 'ingredient', row: ingredients[i] }; }
  }
  for (i = 0; i < menuItems.length; i++) {
    keys = candidateKeys(menuItems[i].item_name);
    for (k = 0; k < keys.length; k++) {
      if (keys[k].indexOf(key) === -1 && key.indexOf(keys[k]) === -1) continue;
      if (Math.min(key.length, keys[k].length) / Math.max(key.length, keys[k].length) < 0.6) continue;
      return { entity_type: 'menu_item', row: menuItems[i] };
    }
  }
  for (i = 0; i < ingredients.length; i++) {
    keys = candidateKeys(ingredients[i].name);
    for (k = 0; k < keys.length; k++) {
      if (keys[k].indexOf(key) === -1 && key.indexOf(keys[k]) === -1) continue;
      if (Math.min(key.length, keys[k].length) / Math.max(key.length, keys[k].length) < 0.6) continue;
      return { entity_type: 'ingredient', row: ingredients[i] };
    }
  }
  if (key.length >= 5) {
    var tolerance = Math.max(1, Math.floor(key.length * 0.22));
    var bestDist = null, bestType = null, bestRow = null;
    for (i = 0; i < menuItems.length; i++) {
      keys = candidateKeys(menuItems[i].item_name);
      for (k = 0; k < keys.length; k++) {
        var cand = keys[k];
        if (Math.abs(cand.length - key.length) > tolerance + 2) continue;
        var d = levenshtein(key, cand);
        if (d <= tolerance && (bestDist === null || d < bestDist)) { bestDist = d; bestRow = menuItems[i]; bestType = 'menu_item'; }
      }
    }
    for (i = 0; i < ingredients.length; i++) {
      keys = candidateKeys(ingredients[i].name);
      for (k = 0; k < keys.length; k++) {
        var cand2 = keys[k];
        if (Math.abs(cand2.length - key.length) > tolerance + 2) continue;
        var d2 = levenshtein(key, cand2);
        if (d2 <= tolerance && (bestDist === null || d2 < bestDist)) { bestDist = d2; bestRow = ingredients[i]; bestType = 'ingredient'; }
      }
    }
    if (bestRow) return { entity_type: bestType, row: bestRow };
  }
  return null;
}

var diff = [];
var unmatched = [];
var lines = [];

items.forEach(function (it) {
  var m = findMatch(it.raw_name);
  if (!m) { unmatched.push(it.raw_name); return; }
  var row = m.row;
  var name = row.item_name || row.name;
  var entry = { id: row.id, entity_type: m.entity_type, label: name };
  var lineParts = [];

  if (it.restock_qty !== undefined && it.restock_qty !== null && it.restock_qty !== '') {
    var qty = Number(it.restock_qty);
    if (qty > 0) {
      entry.restock_qty = qty;
      var curStock = (row.stock_qty === null || row.stock_qty === undefined) ? 0 : row.stock_qty;
      lineParts.push(name + ': stock ' + roundQty(curStock) + ' -> ' + roundQty(curStock + qty));
    }
  }
  if (it.new_price !== undefined && it.new_price !== null && it.new_price !== '' && m.entity_type === 'menu_item') {
    var price = Number(it.new_price);
    if (price > 0) {
      entry.price = price;
      lineParts.push(name + ': price Rs' + row.price + ' -> Rs' + price);
    }
  }
  if (it.mark_unavailable === true && m.entity_type === 'menu_item') {
    entry.available = false;
    lineParts.push(name + ': marked OUT OF STOCK');
  }
  if (it.mark_available === true && m.entity_type === 'menu_item') {
    entry.available = true;
    lineParts.push(name + ': marked back in stock');
  }

  if (lineParts.length) {
    diff.push(entry);
    lines.push(lineParts.join(', '));
  }
});

var reply;
if (diff.length === 0 && unmatched.length === 0) {
  reply = "I didn't catch any specific items to update - can you say the item name and what changed?";
} else {
  reply = '';
  if (lines.length) { reply += 'Here is what I heard:\n' + lines.join('\n') + '\n\nTap Apply to confirm.'; }
  if (unmatched.length) { reply += (lines.length ? '\n\n' : '') + "I couldn't match: " + unmatched.join(', ') + '. Can you clarify those?'; }
}

return [{ json: { reply: reply, pending_update: diff.length ? { kind: 'restock', updates: diff } : null, intent: 'restock_update' } }];

var c = ($('Classify & Extract').first().json.output) || {};
var when = 'soon';
if (c.reminder_due_at) {
  try { when = new Date(c.reminder_due_at).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' }); } catch (e) { when = c.reminder_due_at; }
}
return [{ json: { reply: 'Reminder set for ' + when + ': ' + (c.reminder_text || ''), pending_update: null, intent: 'reminder' } }];

var hook = $('Apply Webhook').first().json;
var body = hook.body || hook;
var who = ($('Verify Staff Apply').first().json || {}).body || {};
return [{ json: {
  kind: body.kind || 'restock',
  updates: Array.isArray(body.updates) ? body.updates : [],
  order: body.order || null,
  staff_email: who.email || 'unknown'
} }];

function unwrap(n) {
  var r = $(n).first().json;
  var b = (r && r.body !== undefined) ? r.body : r;
  return (b && b[0] !== undefined && Array.isArray(b)) ? b[0] : b;
}

var lowStock = unwrap('Check Low Stock') || {};
var openTablesRaw = $('Check Open Tables').first().json;
var openTablesBody = (openTablesRaw && openTablesRaw.body !== undefined) ? openTablesRaw.body : openTablesRaw;
var openTables = Array.isArray(openTablesBody) ? openTablesBody : [];

var existingRaw = $('Get Existing Alerts').first().json;
var existingBody = (existingRaw && existingRaw.body !== undefined) ? existingRaw.body : existingRaw;
var existing = Array.isArray(existingBody) ? existingBody : [];

function alreadyAlerted(table, id) {
  return existing.some(function (e) { return e.related_table === table && String(e.related_id) === String(id); });
}

var out = [];

(lowStock.menu_items || []).forEach(function (mi) {
  if (alreadyAlerted('menu_items', mi.item_name)) return;
  out.push({ json: { text: 'Low stock: ' + mi.item_name + ' (' + mi.stock_qty + ' left, threshold ' + mi.low_stock_threshold + ')', type: 'alert', source: 'automation', related_table: 'menu_items', related_id: mi.item_name } });
});
(lowStock.ingredients || []).forEach(function (ing) {
  if (alreadyAlerted('ingredients', ing.name)) return;
  out.push({ json: { text: 'Low stock: ' + ing.name + ' (' + ing.stock_qty + ' ' + ing.unit + ' left)', type: 'alert', source: 'automation', related_table: 'ingredients', related_id: ing.name } });
});
openTables.forEach(function (t) {
  if (t.minutes_since_activity >= 120) {
    if (alreadyAlerted('table_sessions', t.table_number)) return;
    out.push({ json: { text: 'Table ' + t.table_number + ' has had no activity for ' + t.minutes_since_activity + ' minutes - check on them', type: 'alert', source: 'automation', related_table: 'table_sessions', related_id: t.table_number } });
  }
});

return out;

function norm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function levenshtein(a, b) {
  var m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  var prev = [];
  for (var j = 0; j <= n; j++) prev.push(j);
  for (var i = 1; i <= m; i++) {
    var cur = [i];
    for (var j2 = 1; j2 <= n; j2++) {
      var cost = a[i-1] === b[j2-1] ? 0 : 1;
      cur.push(Math.min(prev[j2] + 1, cur[j2-1] + 1, prev[j2-1] + cost));
    }
    prev = cur;
  }
  return prev[n];
}
function candidateKeys(fullName) {
  var keys = [norm(fullName)];
  var slash = fullName.indexOf(' / ');
  if (slash > -1) keys.push(norm(fullName.slice(0, slash)));
  var noParen = fullName.replace(/\s*\([^)]*\)\s*$/, '').trim();
  if (noParen && noParen !== fullName) keys.push(norm(noParen));
  var dash = fullName.indexOf(' - ');
  if (dash > -1) keys.push(norm(fullName.slice(0, dash)));
  return keys;
}

var invRaw = $('Fetch Menu For Order').first().json;
var inv = (invRaw && invRaw.body !== undefined) ? invRaw.body : invRaw;
inv = (inv && inv[0]) ? inv[0] : inv;
var menuItems = (inv && inv.menu_items) || [];

var c = ($('Classify & Extract').first().json.output) || {};
var rawItems = c.order_items || [];

function findMenuMatch(rawName) {
  var key = norm(rawName);
  if (!key) return null;
  var i, k, keys;
  for (i = 0; i < menuItems.length; i++) {
    keys = candidateKeys(menuItems[i].item_name);
    for (k = 0; k < keys.length; k++) { if (keys[k] === key) return menuItems[i]; }
  }
  for (i = 0; i < menuItems.length; i++) {
    keys = candidateKeys(menuItems[i].item_name);
    for (k = 0; k < keys.length; k++) {
      if (keys[k].indexOf(key) === -1 && key.indexOf(keys[k]) === -1) continue;
      if (Math.min(key.length, keys[k].length) / Math.max(key.length, keys[k].length) < 0.6) continue;
      return menuItems[i];
    }
  }
  if (key.length >= 5) {
    var tolerance = Math.max(1, Math.floor(key.length * 0.22));
    var bestDist = null, bestRow = null;
    for (i = 0; i < menuItems.length; i++) {
      keys = candidateKeys(menuItems[i].item_name);
      for (k = 0; k < keys.length; k++) {
        var cand = keys[k];
        if (Math.abs(cand.length - key.length) > tolerance + 2) continue;
        var d = levenshtein(key, cand);
        if (d <= tolerance && (bestDist === null || d < bestDist)) { bestDist = d; bestRow = menuItems[i]; }
      }
    }
    if (bestRow) return bestRow;
  }
  return null;
}

var cart = [];
var unmatched = [];
rawItems.forEach(function (it) {
  var m = findMenuMatch(it.raw_name);
  if (!m) { unmatched.push(it.raw_name); return; }
  if (m.available === false) { unmatched.push(it.raw_name + ' (currently marked unavailable)'); return; }
  var qty = Math.max(1, Math.round(Number(it.quantity) || 1));
  var existing = null;
  for (var j = 0; j < cart.length; j++) { if (cart[j].menu_item_id === m.id) { existing = cart[j]; break; } }
  if (existing) { existing.quantity += qty; }
  else { cart.push({ menu_item_id: m.id, name: m.item_name, price: Number(m.price), quantity: qty }); }
});

var phone = String(c.customer_phone || '').replace(/\D/g, '');
var orderType = ['delivery','takeaway','dine-in'].indexOf(c.order_type) > -1 ? c.order_type : 'takeaway';
var tableNumber = String(c.table_number || '').trim();
var address = String(c.address || '').trim();

var missing = [];
if (cart.length === 0) missing.push("what to order");
if (phone.length < 10) missing.push("the customer's phone number");
if (orderType === 'dine-in' && !tableNumber) missing.push('the table number');
if (orderType === 'delivery' && !address) missing.push('the delivery address');

var total = cart.reduce(function (s, i) { return s + i.price * i.quantity; }, 0);

var reply, pendingUpdate;
if (missing.length) {
  var lines = cart.map(function (i) { return i.name + ' x' + i.quantity; });
  reply = (lines.length ? 'Got: ' + lines.join(', ') + '. ' : '') +
    'I still need ' + missing.join(' and ') + ' before I can place this order.' +
    (unmatched.length ? ' Also could not match: ' + unmatched.join(', ') + '.' : '');
  pendingUpdate = null;
} else {
  var summary = cart.map(function (i) { return i.name + ' x' + i.quantity + ' (Rs' + (i.price * i.quantity) + ')'; }).join(', ');
  reply = (orderType === 'dine-in' ? 'Table ' + tableNumber : orderType) + ': ' + summary +
    '. Total Rs' + total + '. Tap Place Order to confirm.' +
    (unmatched.length ? ' (Could not match: ' + unmatched.join(', ') + ')' : '');
  pendingUpdate = { kind: 'order', order: {
    order_type: orderType, table_number: tableNumber, address: address,
    pincode: String(c.pincode || ''), customer_phone: phone,
    customer_name: String(c.customer_name || ''), total: total,
    items: cart.map(function (i) { return { name: i.name, quantity: i.quantity, price: i.price }; })
  } };
}

return [{ json: { reply: reply, pending_update: pendingUpdate, intent: 'place_order' } }];

var o = $json.order || {};
var staff = $json.staff_email;
var items = (o.items || []).map(function (i) { return { name: i.name, quantity: i.quantity, price: i.price }; });
return [{ json: {
  customer_phone: o.customer_phone, customer_name: o.customer_name || '',
  order_type: o.order_type, address: o.order_type === 'delivery' ? (o.address || '') : '',
  landmark: '', city: 'Mangaluru', pincode: o.order_type === 'delivery' ? (o.pincode || '') : '',
  table_number: o.order_type === 'dine-in' ? (o.table_number || '') : '', session_id: '',
  total: o.total, source: 'pos', staff: staff, taken_by: staff, items: items
} }];

var hook = $('Transcribe Webhook').first().json;
var body = hook.body || hook;
return [{ json: { audio_base64: body.audio_base64 || '' } }];
